import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Day 16: BBAppends, FILESPATH & Custom Splash Screens","description":"","frontmatter":{},"headers":[],"relativePath":"day16-filespath-splashscreen-and-bbappends.md","filePath":"day16-filespath-splashscreen-and-bbappends.md"}'),p={name:"day16-filespath-splashscreen-and-bbappends.md"};function o(n,e,l,r,d,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="day-16-bbappends-filespath-custom-splash-screens" tabindex="-1">Day 16: BBAppends, FILESPATH &amp; Custom Splash Screens <a class="header-anchor" href="#day-16-bbappends-filespath-custom-splash-screens" aria-label="Permalink to &quot;Day 16: BBAppends, FILESPATH &amp; Custom Splash Screens&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Modify upstream recipes safely using <code>.bbappend</code> files</li><li>Manipulate the <code>FILESEXTRAPATHS</code> variable to override upstream source files</li><li>Apply these concepts to replace the default Yocto boot splash screen with a custom image</li><li>Utilize <code>bitbake-layers show-appends</code> to audit active modifications</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day15-cmake-recipes-and-devshell-debugging.html">Day 15: Devshell Debugging</a></li><li>A custom layer (<code>meta-custom</code>) added to <code>bblayers.conf</code></li></ul></div><hr><h2 id="_1-the-power-of-bbappend" tabindex="-1">1. The Power of <code>.bbappend</code> <a class="header-anchor" href="#_1-the-power-of-bbappend" aria-label="Permalink to &quot;1. The Power of \`.bbappend\`&quot;">​</a></h2><p>You are building a custom embedded device and you realize the SSH server (<code>dropbear</code>) provided by OE-Core has a default configuration file that doesn&#39;t meet your security requirements.</p><p><strong>The Wrong Way:</strong> You open <code>poky/meta/recipes-core/dropbear/dropbear_2022.82.bb</code> and edit it directly. When the next Yocto release comes out, your changes are overwritten or cause massive Git merge conflicts.</p><p><strong>The Yocto Way:</strong> You create a <code>.bbappend</code> file in your <em>custom layer</em>.</p><p>A <code>.bbappend</code> file acts like a patch for a <code>.bb</code> recipe. BitBake parses the original <code>.bb</code> file first, and then parses the <code>.bbappend</code>, allowing you to override variables and append tasks cleanly from outside the original layer.</p><h3 id="rule-of-bbappends" tabindex="-1">Rule of BBAppends <a class="header-anchor" href="#rule-of-bbappends" aria-label="Permalink to &quot;Rule of BBAppends&quot;">​</a></h3><p>The <code>.bbappend</code> filename must exactly match the base <code>.bb</code> filename.</p><ul><li>Base: <code>dropbear_2022.82.bb</code></li><li>Append: <code>dropbear_2022.82.bbappend</code><em>(You can also use the wildcard <code>%</code> for versioning: <code>dropbear_%.bbappend</code>)</em></li></ul><hr><h2 id="_2-overriding-files-with-filesextrapaths" tabindex="-1">2. Overriding Files with <code>FILESEXTRAPATHS</code> <a class="header-anchor" href="#_2-overriding-files-with-filesextrapaths" aria-label="Permalink to &quot;2. Overriding Files with \`FILESEXTRAPATHS\`&quot;">​</a></h2><p>When a recipe fetches local files using <code>file://</code>, it searches directories listed in the <code>FILESPATH</code> variable.</p><p>By default, the original layer&#39;s directories are searched first. If you want BitBake to use <em>your</em> custom configuration file instead of the original one, you must prepend your layer&#39;s directory to the search path.</p><p>You do this using the <code>FILESEXTRAPATHS</code> variable inside your <code>.bbappend</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In meta-custom/recipes-core/dropbear/dropbear_%.bbappend</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Prepend our layer&#39;s files/ directory to the search path.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Notice the := operator (immediate expansion) and the :prepend operator.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The trailing colon (:) is critical! It acts as a directory separator.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FILESEXTRAPATHS:prepend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">THISDIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/files:&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Add extra configuration flags to the original recipe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EXTRA_OECONF</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;--disable-weak-ciphers&quot;</span></span></code></pre></div><p>Now, if you place a file named <code>dropbear.default</code> inside <code>meta-custom/recipes-core/dropbear/files/</code>, BitBake will use yours instead of the one in OE-Core!</p><hr><h2 id="_3-practical-example-customizing-the-splash-screen" tabindex="-1">3. Practical Example: Customizing the Splash Screen <a class="header-anchor" href="#_3-practical-example-customizing-the-splash-screen" aria-label="Permalink to &quot;3. Practical Example: Customizing the Splash Screen&quot;">​</a></h2><p>Let&#39;s apply these concepts to replace the default Yocto Project boot splash screen with your company&#39;s logo.</p><p>The recipe responsible for the splash screen in Yocto is <code>psplash</code>.</p><h3 id="step-1-create-the-bbappend-structure" tabindex="-1">Step 1: Create the BBAppend Structure <a class="header-anchor" href="#step-1-create-the-bbappend-structure" aria-label="Permalink to &quot;Step 1: Create the BBAppend Structure&quot;">​</a></h3><p>Inside your custom layer, mirror the directory structure of the original recipe:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meta-custom/recipes-core/psplash/files/</span></span></code></pre></div><p>Create the append file <code>meta-custom/recipes-core/psplash/psplash_%.bbappend</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Prioritize our files/ directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FILESEXTRAPATHS:prepend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">THISDIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/files:&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># We define a new custom logo. The psplash recipe uses the SPLASH_IMAGES variable.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># We append our custom image definition to it.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SPLASH_IMAGES:append</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot; file://custom-logo.png;outsuffix=custom&quot;</span></span></code></pre></div><h3 id="step-2-provide-the-custom-image" tabindex="-1">Step 2: Provide the Custom Image <a class="header-anchor" href="#step-2-provide-the-custom-image" aria-label="Permalink to &quot;Step 2: Provide the Custom Image&quot;">​</a></h3><p>Create a PNG image named <code>custom-logo.png</code> and place it in the <code>files/</code> directory you just created.</p><p><em>Note: The image should not have an alpha channel (transparency) as the framebuffer might not support it cleanly.</em></p><h3 id="step-3-build-and-test" tabindex="-1">Step 3: Build and Test <a class="header-anchor" href="#step-3-build-and-test" aria-label="Permalink to &quot;Step 3: Build and Test&quot;">​</a></h3><p>If you have <code>psplash</code> installed in your image, rebuild it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core-image-minimal</span></span></code></pre></div><p>Boot the image in QEMU. You should see your custom logo during the boot process instead of the Yocto logo!</p><hr><h2 id="_4-auditing-appends" tabindex="-1">4. Auditing Appends <a class="header-anchor" href="#_4-auditing-appends" aria-label="Permalink to &quot;4. Auditing Appends&quot;">​</a></h2><p>As your project grows, you might have dozens of <code>.bbappend</code> files modifying core recipes. If a build suddenly breaks, it can be hard to track down which append is causing the issue.</p><p>BitBake provides a command to list all active appends:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake-layers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show-appends</span></span></code></pre></div><p><strong>Output Example:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>State of append files:</span></span>
<span class="line"><span>dropbear_2022.82.bb:</span></span>
<span class="line"><span>  /path/to/meta-custom/recipes-core/dropbear/dropbear_%.bbappend</span></span>
<span class="line"><span>psplash_git.bb:</span></span>
<span class="line"><span>  /path/to/meta-raspberrypi/recipes-core/psplash/psplash_%.bbappend</span></span>
<span class="line"><span>  /path/to/meta-custom/recipes-core/psplash/psplash_%.bbappend</span></span></code></pre></div><p><em>Notice how <code>psplash</code> has two appends applied! One from <code>meta-raspberrypi</code> and one from your <code>meta-custom</code>.</em></p><hr><h2 id="_5-course-conclusion" tabindex="-1">5. Course Conclusion <a class="header-anchor" href="#_5-course-conclusion" aria-label="Permalink to &quot;5. Course Conclusion&quot;">​</a></h2><p>Congratulations! 🎉 You have completed the 16-Day Embedded Linux and Yocto Masterclass.</p><p>You now possess the skills to:</p><ul><li>Architect custom embedded Linux distributions</li><li>Navigate the OpenEmbedded build system and BitBake engine</li><li>Write custom recipes and <code>.bbappend</code> files</li><li>Integrate third-party BSP layers for hardware bring-up</li><li>Debug complex C/C++ cross-compilation failures</li></ul><p><strong>Next Steps:</strong> Check out the <a href="/renode-emulation-guide.html">Renode Emulation Guide</a> to learn how to boot full Zynq-7000 FPGA-SoC Linux images entirely in software, or review the <a href="/cheat-sheet.html">BitBake Cheat Sheet</a> for a quick reference on your next project.</p><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day15-cmake-recipes-and-devshell-debugging">← Day 15: Devshell Debugging</a><a href="/cheat-sheet">BitBake Cheat Sheet →</a></div>`,50)])])}const b=a(p,[["render",o]]);export{u as __pageData,b as default};
